import { useState } from "react";
import { tiles } from '../config';
import useStore from '../store';
import { SketchPicker } from 'react-color';

export default function Sidebar() {

  const [visible, setVisible] = useState(false);

  const actions = useStore(state => state.actions);
  const showSidebar = useStore(state => state.showSidebar);
  const tileType = useStore(state => state.tileType);
  const layingAngle = useStore(state => state.layingAngle);
  const layout = useStore(state => state.layout);
  const tile = useStore(state => state.tile);
  const disableChess = useStore(state => state.disableChess);
  const disableSkew = useStore(state => state.disableSkew);
  const skewAmount = useStore(state => state.skewAmount);
  const groutSize = useStore(state => state.groutSize);
  const groutColor = useStore(state => state.groutColor);

  const [tab, setTab] = useState('product');
  const [colorpickerVisible, setColorpickerVisible] = useState(false);

  const angles = [0, 45, 90, 135, 180];

  const [search, setSearch] = useState('');

  return (
    <div className={"sidebar" + (showSidebar? ' show' : '')} >
      <span className="toggle-sidebar" onClick={()=>{
        actions.toggleSidebar();
      }} ></span>
      <div className="sidebar-tabs">
        <span onClick={()=>setTab('product')} className={"sidebar-tab" + (tab=='product'?' active':'')} >Product</span>
        <span onClick={()=>setTab('layout')} className={"sidebar-tab" + (tab=='layout'?' active':'')} >Layout</span>
        <span onClick={()=>setTab('grout')} className={"sidebar-tab" + (tab=='grout'?' active':'')} >Grout</span>
      </div>
      <div className="sidebar-contents">
        <div className={"sidebar-tab-content" + (tab=='product'?' active':'')}>
          <input className="tile-search" placeholder="Search" onInput={(e)=>{setSearch(e.target.value)}} ></input>
        </div>
        <div className={"sidebar-tab-content" + (tab=='layout'?' active':'')}>
          <div>Laying angle: 
            { angles.map(function(item, index) {
              return (
                <span key={index} className={"laying-angle-select" + (layingAngle==item?' active':'')} onClick={()=>{actions.setAngle(item)}} >{item}&deg;</span>
              );
            }) }
          </div>
          <div className={"layout-types" + (disableChess?' disable-chess':'') + (disableSkew?' disable-skew':'')}>
            <div className={"layout-types-item" + (layout=='standard'?' active':'')} onClick={()=>{actions.setLayout('standard')}} >
              <img src="/assets/images/square.png"></img><br/>Standard
            </div>
            <div className={"layout-types-item chess" + (layout=='chess'?' active':'')} onClick={()=>{actions.setLayout('chess')}} >
              <img src="/assets/images/chess.png"></img><br/>Chess
            </div>
            <div className={"layout-types-item skew" + (layout=='skew'?' active':'')} onClick={()=>{actions.setLayout('skew')}} >
              <img src="/assets/images/skew.png"></img><br/>Horizontal Skew
            </div>
            <div className={"layout-types-item skew" + (layout=='skewvert'?' active':'')} onClick={()=>{actions.setLayout('skewvert')}} >
              <img src="/assets/images/skewVert.png"></img><br/>Vertical Skew
            </div>
          </div>
          <div className={"skew-amounts" + (layout=='skew'||layout=='skewvert'?' active':'')}>
            <span className={"skew-amounts-item" + (skewAmount==0.25?' active':'')} onClick={()=>actions.setSkewAmount(0.25)} >1/4</span>
            <span className={"skew-amounts-item" + (skewAmount==0.5?' active':'')} onClick={()=>actions.setSkewAmount(0.5)} >1/2</span>
            <span className={"skew-amounts-item" + (skewAmount==0.75?' active':'')} onClick={()=>actions.setSkewAmount(0.75)} >3/4</span>
          </div>
        </div>
        <div className={"sidebar-tab-content" + (tab=='grout'?' active':'')}>
          Grout size:
          &nbsp;<input type="range" min="0" max="24" value={groutSize} onChange={e=>{ actions.setGroutSize(e.target.value) }} ></input> { groutSize }mm
          <br></br><br></br>
          Grout color: 
          <div
            className="color-picker-wrapper"
          >
            <div
              style={{
                backgroundColor: groutColor || '#ffffff',
              }}
              className="btn-grout-color"
              onClick={()=>{ setColorpickerVisible(true) }}
            ></div>
            { colorpickerVisible? (
              <div className="colorpop" >
                <div className="cover" onClick={()=>{ setColorpickerVisible(false); }} ></div>
                <SketchPicker
                  color={ groutColor }
                  onChangeComplete={color=>{actions.setGroutColor(color.hex)}}
                  disableAlpha={true}
                  presetColors={['#FFE6A6', '#98745E', '#E5D9CD', '#BFBFBF']}
                ></SketchPicker>
              </div>
            ) : null }
            
          </div>
        </div>
      </div>
      <div className={'tiles-list type-' + tileType}>
        {
          tiles.map((tile, i) => {
            let type = '';
            if (tile.floor) {
              type += 'type-floor';
            }
            if (tile.wall) {
              type += ' type-wall';
            }
            return tile.name.toLowerCase().includes(search.toLowerCase()) ? (
              <div className={"sidebar-tile-item " + type} key={i} onClick={() => {
                actions.applyTile(tile, 'sidebar-tile-img-' + i);
              }} >
                <img id={"sidebar-tile-img-" + i} className="tile-item-img" src={tile.src} ></img>
                <div className="tile-item-description">
                  <b>{tile.name}</b><br/>
                  <span>{tile.width}cm X {tile.height}cm</span><br/>
                  <span>Finish: {tile.finish}</span>
                </div>
              </div>
            ) : null;
          })
        }
      </div>
    </div>
  );
}