import React, { useRef, useState } from 'react';
import { Canvas, useFrame, useThree } from 'react-three-fiber';
import Sidebar from './Sidebar/Sidebar';
import Room from './Room/Room';
import useStore from './store';
import { rooms } from './config';


export default function App() {

  const room = useStore(state => state.room);
  const actions = useStore(state => state.actions);
  const showRoomModal = useStore(state => state.showRoomModal);

  const [roomsTab, setRoomsTab] = useState(0);

  return (
    <div className="main" >
      <canvas id="canvas-texture"></canvas>
      <div className="canvas-holder">
        <Canvas camera={{ position: room.camPos, fov: 40 }} pixelRatio={window.devicePixelRatio}
          onCreated={ (state) => { actions.init(state.camera);} }
        >
          <color attach="background" args={[0xffffff]} />
          <ambientLight color={0xffffff} intensity={0.7} />
          <Room {...room} ></Room>
        </Canvas>
      </div>
      <img className="foreground-img" src={'/assets/images/rooms/' + room.back}></img>
      <img className="foreground-img v2" src={'/assets/images/rooms/' + room.back}></img>
      <img className="background-img" src={'/assets/images/rooms/' + room.front}></img>
      <Sidebar></Sidebar>
      <button className="btn-select-room" onClick={() => actions.showRoomSelect(true)} >Select Room</button>
      {
        showRoomModal? (
          <div className="room-modal">
            <div className="room-modal-inner">
              <span onClick={()=>actions.showRoomSelect(false)} className="btn-close-modal" >&#x2716;</span>
              <h3>Select Room</h3>
              <div className="room-modal-tabs">
                {
                  rooms.map((r, i) => {
                    return (
                      <span key={i} onClick={()=>setRoomsTab(i)} className={"room-modal-tab" + (roomsTab==i?' active':'')} >{ r.type }</span>
                    );
                  })
                }
              </div>
              {
                rooms.map((g, i) => {
                  return (
                    <div key={i} className={"room-modal-tab-content" + (roomsTab==i?' active':'')}>
                      {
                        g.rooms.map((r, j)=>{
                          return (
                          <div key={j} onClick={()=>{actions.setRoom(r); actions.showRoomSelect(false); }} className="room-modal-item">
                            <div className="room-modal-item-image">
                              <img src={'/assets/images/rooms/' + r.back}></img>
                              <img src={'/assets/images/rooms/' + r.front}></img>
                            </div>
                            <b>{r.name}</b>
                          </div>)
                        })
                      }
                    </div>
                  );
                })
              }
            </div>
          </div>
        ) : null
      }
    </div>
  )
}
