import create from 'zustand';
import * as THREE from 'three';
import { tiles, rooms } from './config';
import { useThree } from 'react-three-fiber';

const [useStore, api] = create((set, get) => {
  return {
    showSidebar: false,
    tileType: 'all',
    layingAngle: 0,
    layout: 'standard',
    tile: null,
    wall: null,
    disableChess: false,
    disableSkew: false,
    skewAmount: 0,
    room: rooms[0].rooms[0],
    showRoomModal: false,
    camera: null,
    groutSize: 3,
    groutColor: '#ffffff',

    mutation: {

    },

    actions: {
      init(camera) {
        set({camera});
        const {room} = get();
        camera.position.copy(new THREE.Vector3(...room.camPos));
        camera.lookAt(new THREE.Vector3(...room.camPos));
        camera.updateProjectionMatrix();
      },
      toggleSidebar(b) {
        const { showSidebar } = get();

        if (b === undefined) {
          set({ showSidebar: !showSidebar });
        } else {
          set({ showSidebar: b });
        }
      },
      setWall(wall) {
        set({
          wall,
          tileType: wall.type,
          layingAngle: wall.angle || 0,
          layout: wall.layout || 'standard',
          tile: wall.tile,
          disableChess: wall.tile && wall.tile.chess === false,
          disableSkew: wall.tile && wall.tile.skew === false,
          skewAmount: wall.skewAmount || 0,
          groutColor: wall.groutColor || '#ffffff',
          groutSize: wall.groutSize || 4,
        });
      },
      applyTile(tile, id) {
        let { wall } = get();
        if (wall) {
          wall.tile = tile;
          wall.imgid = id;
          if (tile.chess === false) {
            wall.layout = 'standard';
            set({layout: 'standard'});
          } else if (tile.skew === false && (wall.layout == 'skew' || wall.layout == 'skewvert')) {
            wall.layout = 'standard';
            set({layout: 'standard'});
          }
          set({
            disableChess: tile.chess === false,
            disableSkew: tile.skew === false,
          });
          updateWallTexture(wall);
        }
      },
      setAngle(angle) {
        set({
          layingAngle: angle
        });

        let { wall } = get();
        if (wall) {
          wall.angle = angle;
          updateWallTexture(wall);
        }
      },
      setLayout(layout) {
        set({layout});

        if (layout == 'skew' || layout == 'skewvert') {
          set({
            skewAmount: 0.25,
          });
        }

        let { wall } = get();
        if (wall) {
          wall.layout = layout;
          wall.skewAmount = 0.25;
          updateWallTexture(wall);
        }
      },
      setSkewAmount(skewAmount) {
        set({skewAmount});

        let { wall } = get();
        if (wall) {
          wall.skewAmount = skewAmount;
          updateWallTexture(wall);
        }
      },
      showRoomSelect(b) {
        set({showRoomModal: b});
      },
      setRoom(room) {
        set({room, wall: null});
      },
      setGroutSize(size) {
        const {wall} = get();
        if (wall) {
          wall.groutSize = size;
          updateWallTexture(wall);
        }

        set({groutSize: size});
      },
      setGroutColor(color) {
        const {wall} = get();
        if (wall) {
          wall.groutColor = color;
          updateWallTexture(wall);
        }

        set({groutColor: color});
      }
    }
  }
});

function updateWallTexture(wall) {
  if (wall && wall.tile && wall.imgid) {
    if (wall.material.map) {
      wall.material.map.dispose();
    }
    wall.material.map = createCanvasTexture(wall);
    wall.material.color = null;
    wall.material.needsUpdate = true;
  }
}

function createCanvasTexture(wall) {
  const res = 5;
  const canvas = document.getElementById('canvas-texture');
  const ctx = canvas.getContext('2d');
  const width = wall.width * res;
  const height = wall.height * res;
  canvas.width = width;
  canvas.height = height;
  ctx.clearRect(0, 0, width, height);
  ctx.fillStyle= wall.groutColor || "#ffffff";
  ctx.fillRect(0, 0, width, height);

  const tile = wall.tile;
  const angle = wall.angle || 0;
  const imgid = wall.imgid;

  const gap = wall.groutSize !== undefined? wall.groutSize / 10 : 0.3;
  const nx = Math.ceil(wall.width / (tile.width + gap));
  const ny = Math.ceil(wall.height / (tile.height + gap));
  
  const img = document.getElementById(imgid);

  const d = (tile.d || tile.width) + gap * (tile.grx || 1);
  let dx = (tile.dx || 0);
  dx = dx > 0? (dx + gap * (tile.grx || 1) / 2) : 0;
  let dy = (tile.dy || tile.height) + gap * (tile.gry || 1);

  var skewAmount = wall.skewAmount || 0.25;

  var pw, ph;
  if (angle == 0 || angle == 180) {
    pw = width;
    ph = height;
  } else if (angle == 90) {
    pw = height;
    ph = width;
  } else {
    pw = ph = Math.max(width, height) * 1.5;  
  }
  ctx.translate(pw / 2, ph /2);
  ctx.rotate(angle * Math.PI / 180);

  var x0 = -pw / 2;
  var y0 = -ph / 2;
  var ix = 0;
  var iy = 0;

  var y = y0;
  while(true) {
    var x = x0;
    if (iy % 2 == 1) {
      x += dx;
    }

    ix = 0;
    while(true) {
      if (wall.layout == 'chess') {
        var draw = (tile.shape == 'rect' && (ix + iy) % 2 == 0) || (tile.shape == 'diamond' && iy % 2 == 0);
        if (draw) {
          ctx.drawImage(img,
            x * res,
            y * res,
            tile.width * res,
            tile.height * res,
          );
        }
      } else if (wall.layout == 'skew') {
        var ddx = 0, ddy = 0;
        if (iy % 2 == 1) {
          ddx = tile.width * skewAmount;
        }
        ctx.drawImage(img,
          (x + ddx) * res,
          y * res,
          tile.width * res,
          tile.height * res,
        );
      } else if (wall.layout == 'skewvert') {
        var ddx = 0, ddy = 0;
        if (ix % 2 == 1) {
          ddy = tile.height * skewAmount;
        }
        ctx.drawImage(img,
          x * res,
          (y + ddy) * res,
          tile.width * res,
          tile.height * res,
        );
      } else {
        ctx.drawImage(img,
          x * res,
          y * res,
          tile.width * res,
          tile.height * res,
        );
      }

      x += d;
      if (x > pw / 2) {
        break;
      }
      ix++;
    }
    iy++;
    y += dy;
    if (y > ph / 2) {
      break;
    }
  }

  return new THREE.CanvasTexture(canvas);
}

export default useStore;
