import { useRef, useState } from "react";
import * as THREE from 'three';
import useStore from '../store';
import { useFrame, useThree } from 'react-three-fiber';

function Wall(props) {
  const [hovered, setHovered] = useState(false);

  const [material, setMaterial] = useState(new THREE.MeshPhongMaterial({color:props.color || 0xd4dbff, emissive:0x2a6bcc, emissiveIntensity: 0 }));

  const actions = useStore(state => state.actions);

  let ref = useRef();
  props.wall.material = material;
  props.wall.type = props.type;

  return (
    <mesh
    ref={ref}
    onPointerOver={()=>{
      setHovered(true);
      material.emissiveIntensity = 0.6;
      material.needsUpdate = true;
    }}
    onPointerOut={()=>{
      setHovered(false);
      material.emissiveIntensity = 0;
      material.needsUpdate = true;
    }}
    onClick={()=>{
      actions.setWall(props.wall);
      actions.toggleSidebar(true);
    }}
    position={props.wall.position} rotation={props.wall.rotation}
    material={material}
    >
      <planeGeometry attach="geometry" args={[props.wall.width, props.wall.height]} ></planeGeometry>
    </mesh>
  );
}

export default function Room(props) {
  const { walls, floor} = props;

  const { invalidate, camera } = useThree();

  const room = useStore(store => store.room);

  camera.position.copy(new THREE.Vector3(...room.camPos));
  camera.lookAt(...room.look);
  camera.fov = room.fov || 40;
  camera.updateProjectionMatrix();
  invalidate();

  return (
    <group>
      { walls.map(function(wall, i) {
        return (
          <Wall key={i} type="wall" wall={wall} ></Wall>
        );
      }) }

      <Wall type="floor" wall={floor} ></Wall>
    </group>
  );
}
